def add_check_digit(number):
    factors = [2, 3, 4, 5, 6, 7]
    product_sum = 0
    number = str(number)

    for i, digit in enumerate(reversed(number)):
        if i < len(factors):
            factor = factors[i]
        else:
            factor = factors[i % len(factors)]
        product_sum += int(digit) * factor

    remainder = product_sum % 11
    if remainder == 1:
        check_digit = 'X'
    else:
        check_digit = str(11 - remainder)

    return f"{number}{check_digit}"
```

